import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, issueInvoice, invoiceTotals } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';
import { createCreditNote } from '../src/credits.js';

test('createCreditNote creates a credit note for an issued invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 2 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const r = createCreditNote(issued.value, { amount: 50, reason: 'Damaged goods', date: '2026-10-10' }, []);
  assert.equal(r.ok, true);
  assert.equal(r.value.number, 'CN-2026-0001');
  assert.equal(r.value.invoiceNumber, issued.value.number);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.amount, 50);
  assert.equal(r.value.reason, 'Damaged goods');
  assert.equal(r.value.date, '2026-10-10');
});

test('createCreditNote works on partially_paid invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 5 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const partial = recordPayment(issued.value, { amount: 30, date: '2026-10-10' });
  const r = createCreditNote(partial.value, { amount: 50, reason: 'Partial refund', date: '2026-10-15' }, []);
  assert.equal(r.ok, true);
  assert.equal(r.value.number, 'CN-2026-0001');
});

test('createCreditNote works on paid invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 2 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const totals = invoiceTotals(issued.value);
  const paid = recordPayment(issued.value, { amount: totals.value.total, date: '2026-10-10' });
  const r = createCreditNote(paid.value, { amount: 50, reason: 'Overpayment refund', date: '2026-10-15' }, []);
  assert.equal(r.ok, true);
  assert.equal(r.value.number, 'CN-2026-0001');
});

test('createCreditNote rejects draft invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 2 }],
  });
  const r = createCreditNote(invoice.value, { amount: 50, reason: 'Refund', date: '2026-10-10' }, []);
  assert.deepEqual(r, { ok: false, error: 'NOT_ISSUED' });
});

test('createCreditNote rejects null/invalid invoice', () => {
  const r = createCreditNote(null, { amount: 50, reason: 'Refund', date: '2026-10-10' }, []);
  assert.deepEqual(r, { ok: false, error: 'NOT_ISSUED' });
});

test('createCreditNote rejects zero amount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 2 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const r = createCreditNote(issued.value, { amount: 0, reason: 'Refund', date: '2026-10-10' }, []);
  assert.deepEqual(r, { ok: false, error: 'AMOUNT_INVALID' });
});

test('createCreditNote rejects negative amount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 2 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const r = createCreditNote(issued.value, { amount: -50, reason: 'Refund', date: '2026-10-10' }, []);
  assert.deepEqual(r, { ok: false, error: 'AMOUNT_INVALID' });
});

test('createCreditNote rejects fractional amount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 2 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const r = createCreditNote(issued.value, { amount: 50.5, reason: 'Refund', date: '2026-10-10' }, []);
  assert.deepEqual(r, { ok: false, error: 'AMOUNT_INVALID' });
});

test('createCreditNote rejects non-numeric amount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 2 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const cases = ['50', true, null];
  for (const amount of cases) {
    const r = createCreditNote(issued.value, { amount, reason: 'Refund', date: '2026-10-10' }, []);
    assert.deepEqual(r, { ok: false, error: 'AMOUNT_INVALID' }, `should reject amount=${amount}`);
  }
});

test('createCreditNote rejects invalid date format', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 2 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const cases = ['2026-10-1', '2026/10/10', 'not-a-date', undefined];
  for (const date of cases) {
    const r = createCreditNote(issued.value, { amount: 50, reason: 'Refund', date }, []);
    assert.deepEqual(r, { ok: false, error: 'DATE_INVALID' }, `should reject date=${date}`);
  }
});

test('createCreditNote rejects credit amount exceeding invoice total', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 2 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const totals = invoiceTotals(issued.value);
  const r = createCreditNote(issued.value, { amount: totals.value.total + 1, reason: 'Refund', date: '2026-10-10' }, []);
  assert.deepEqual(r, { ok: false, error: 'CREDIT_TOO_HIGH' });
});

test('createCreditNote accepts credit amount equal to invoice total', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 2 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const totals = invoiceTotals(issued.value);
  const r = createCreditNote(issued.value, { amount: totals.value.total, reason: 'Full refund', date: '2026-10-10' }, []);
  assert.equal(r.ok, true);
  assert.equal(r.value.amount, totals.value.total);
});

test('createCreditNote generates sequential numbers within a year', () => {
  const invoice1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 1 }],
  });
  const issued1 = issueInvoice(invoice1.value, []);
  const r1 = createCreditNote(issued1.value, { amount: 30, reason: 'Refund 1', date: '2026-10-10' }, []);
  assert.equal(r1.value.number, 'CN-2026-0001');

  const invoice2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-15',
    lines: [{ sku: 'STICKER', qty: 2 }],
  });
  const issued2 = issueInvoice(invoice2.value, ['INV-2026-0001']);
  const r2 = createCreditNote(issued2.value, { amount: 50, reason: 'Refund 2', date: '2026-10-20' }, ['CN-2026-0001']);
  assert.equal(r2.value.number, 'CN-2026-0002');
});

test('createCreditNote resets counter per year', () => {
  const invoice2026 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 1 }],
  });
  const issued2026 = issueInvoice(invoice2026.value, []);
  const r2026 = createCreditNote(issued2026.value, { amount: 30, reason: 'Refund', date: '2026-10-10' }, ['CN-2026-0005']);

  const invoice2027 = createInvoice({
    customerId: 'C-001',
    issueDate: '2027-01-15',
    lines: [{ sku: 'STICKER', qty: 2 }],
  });
  const issued2027 = issueInvoice(invoice2027.value, []);
  const r2027 = createCreditNote(issued2027.value, { amount: 50, reason: 'Refund', date: '2027-01-20' }, ['CN-2026-0005']);

  assert.equal(r2026.value.number, 'CN-2026-0006');
  assert.equal(r2027.value.number, 'CN-2027-0001');
});

test('createCreditNote pads counter to 4 digits', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 1 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const r = createCreditNote(issued.value, { amount: 30, reason: 'Refund', date: '2026-10-10' }, []);
  assert.equal(r.value.number, 'CN-2026-0001');
});

test('createCreditNote ignores invoice numbers when generating credit note number', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 1 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const r = createCreditNote(issued.value, { amount: 30, reason: 'Refund', date: '2026-10-10' }, [
    'INV-2026-0001',
    'INV-2026-0002',
    'INV-2026-0003',
  ]);
  assert.equal(r.value.number, 'CN-2026-0001');
});

test('createCreditNote with mixed invoice and credit note numbers', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 1 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const r = createCreditNote(issued.value, { amount: 30, reason: 'Refund', date: '2026-10-10' }, [
    'INV-2026-0001',
    'CN-2026-0001',
    'INV-2026-0002',
    'CN-2026-0002',
  ]);
  assert.equal(r.value.number, 'CN-2026-0003');
});

test('createCreditNote returns all required fields', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 2 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const r = createCreditNote(issued.value, { amount: 50, reason: 'Damaged goods', date: '2026-10-10' }, []);
  assert.equal(r.ok, true);
  assert.ok('number' in r.value);
  assert.ok('invoiceNumber' in r.value);
  assert.ok('customerId' in r.value);
  assert.ok('amount' in r.value);
  assert.ok('reason' in r.value);
  assert.ok('date' in r.value);
});

test('createCreditNote preserves invoice number and customer ID', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 2 }],
  });
  const issued = issueInvoice(invoice.value, ['INV-2026-0010']);
  const r = createCreditNote(issued.value, { amount: 50, reason: 'Refund', date: '2026-10-10' }, []);
  assert.equal(r.value.invoiceNumber, 'INV-2026-0011');
  assert.equal(r.value.customerId, 'C-003');
});

test('createCreditNote accepts null existingNumbers', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 2 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const r = createCreditNote(issued.value, { amount: 50, reason: 'Refund', date: '2026-10-10' }, null);
  assert.equal(r.ok, true);
  assert.equal(r.value.number, 'CN-2026-0001');
});

test('createCreditNote with partial amount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const totals = invoiceTotals(issued.value);
  const partialCredit = Math.floor(totals.value.total / 2);
  const r = createCreditNote(issued.value, { amount: partialCredit, reason: 'Partial refund', date: '2026-10-10' }, []);
  assert.equal(r.ok, true);
  assert.equal(r.value.amount, partialCredit);
  assert.ok(r.value.amount < totals.value.total);
});

test('createCreditNote with various reasons', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 2 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const reasons = ['Damaged goods', 'Wrong quantity shipped', 'Price adjustment', 'Customer request'];
  for (let i = 0; i < reasons.length; i++) {
    const r = createCreditNote(issued.value, { amount: 30, reason: reasons[i], date: '2026-10-10' }, [
      ...reasons.slice(0, i).map((_, idx) => `CN-2026-000${idx + 1}`),
    ]);
    assert.equal(r.ok, true);
    assert.equal(r.value.reason, reasons[i]);
  }
});

test('createCreditNote on invoice with discount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const totals = invoiceTotals(issued.value);
  const r = createCreditNote(issued.value, { amount: 5000, reason: 'Refund', date: '2026-10-10' }, []);
  assert.equal(r.ok, true);
  assert.ok(r.value.amount <= totals.value.total);
});

test('createCreditNote on invoice with voucher', () => {
  const { applyVoucher } = await import('../src/invoices.js');
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const vouchered = applyVoucher(issued.value, { code: 'SAVE10', amount: 5000 });
  const totals = invoiceTotals(vouchered.value);
  const r = createCreditNote(vouchered.value, { amount: 10000, reason: 'Refund', date: '2026-10-10' }, []);
  assert.equal(r.ok, true);
  assert.ok(r.value.amount <= totals.value.total);
});

