});

test('createCreditNote resets counter per year', () => {
  const invoice2026 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 1 }],
  });
  const issued2026 = issueInvoice(invoice2026.value, []);
  const r2026 = createCreditNote(issued2026.value, { amount: 30, reason: 'Refund', date: '2026-10-10' }, ['CN-2026-0005']);

  const invoice2027 = createInvoice({
    customerId: 'C-001',
    issueDate: '2027-01-15',
    lines: [{ sku: 'STICKER', qty: 2 }],
  });
