  const r2027 = createCreditNote(issued2027.value, { amount: 50, reason: 'Refund', date: '2027-01-20' }, ['CN-2026-0005']);

  assert.equal(r2026.value.number, 'CN-2026-0006');
  assert.equal(r2027.value.number, 'CN-2027-0001');
});

test('createCreditNote pads counter to 4 digits', () => {
